import assert from "node:assert/strict";
const root = process.env.REPO_PATH!;
const { loadPlayer } = await import(root + "/packages/four-shogi/bench/baseline.ts");
const { experimentStarts, playAnalysisSingles } = await import(root + "/packages/four-shogi/bench/searchExperiment.ts");
const { seatLineup, summarizeSingles } = await import(root + "/packages/four-shogi/bench/singlesMeasurement.ts");
const { summarizeTimes } = await import(root + "/packages/four-shogi/bench/measurement.ts");
const { sides } = await import(root + "/packages/four-shogi/src/types.ts");
const { aiJobRequestSchema, aiJobSnapshotSchema, aiRequestFingerprint, createAiRequestId, aiCpuProfiles } = await import(root + "/packages/protocol/src/fourShogiAi.ts");
const base = process.env.AI_CPU_SMOKE_URL!, secret = process.env.AI_CPU_SMOKE_SECRET!, codeVersion = process.env.AI_CPU_SMOKE_CODE_VERSION!, modelId = process.env.AI_CPU_SMOKE_MODEL_ID!;
const principal = "d".repeat(64);
async function call(path: string, method = "GET", body?: unknown) {
  const response = await fetch(base + path, { method, redirect: "manual", headers: { Authorization: "Bearer " + secret, "Content-Type": "application/json", "X-AI-Principal": principal, "X-AI-Instance": serviceInstance }, body: body ? JSON.stringify(body) : undefined, signal: AbortSignal.timeout(5000) });
  assert(response.ok, "Profile comparison HTTP " + response.status);
  return response.json();
}
let serviceInstance = "";
const health = await call("/v1/health"); serviceInstance = health.serviceInstanceId;
assert.equal(health.codeVersion, codeVersion); assert.equal(health.modelId, modelId);
const frozen = await loadPlayer("frozen");
const rows: object[] = [], selections: object[] = [];
try {
  const starts = await experimentStarts([false, true], 1, 19410);
  for (const profile of ["trial-100ms", "trial-500ms"] as const) for (const start of starts) {
    const samples = [];
    for (const seat of sides) {
      const events = structuredClone(start.replay.events), matchId = crypto.randomUUID();
      const candidate = async (position: any) => {
        const currentHealth = await call("/v1/health");
        const request = aiJobRequestSchema.parse({ schemaVersion: 1, serviceInstanceId: serviceInstance, requestId: createAiRequestId(currentHealth.requestWindow), principal, codeVersion, engineVersion: health.engineVersion, modelId, stateHash: position.stateHash, context: { kind: "cpu", roomId: "19400", instanceId: matchId, matchId, revision: events.length, side: position.state.turn, deadlineAtMs: Date.now() + 5000 }, lifetimeMs: 4000, budget: aiCpuProfiles[profile], position: { ...start.replay, initial: { ...start.replay.initial, players: { south: "south", west: "west", north: "north", east: "east" } }, events, eventOffset: events.length } });
        const fingerprint = await aiRequestFingerprint(request), began = performance.now();
        let job = aiJobSnapshotSchema.parse(await call("/v1/jobs", "POST", request));
        while (job.status === "queued" || job.status === "running") { assert(performance.now() - began < 5000); await Bun.sleep(20); job = aiJobSnapshotSchema.parse(await call("/v1/jobs/" + job.jobId)); }
        assert(["completed", "failed"].includes(job.status)); assert.equal(job.inputHash, fingerprint); assert.equal(job.stateHash, position.stateHash);
        if (job.status === "failed") {
          assert.equal(job.error, "model_not_used");
          const fallback = frozen.selector(position.state);
          selections.push({ profile, restricted: position.state.threePlayerAttackProhibited, seat, stateHash: position.stateHash, wallMs: performance.now() - began, timing: job.timing, versions: null, model: { requestedModelId: modelId, usedModelId: null, inferenceCount: 0, fallbackReason: job.error }, diagnostics: fallback.stats, fallback: "fixed current Lv2, work2048" });
          return { ...fallback, details: null };
        }
        const result = job.result as any;
        assert(result.model.usedModelId === modelId && result.model.inferenceCount > 0 || result.evaluation.evaluationKind === "terminal");
        selections.push({ profile, restricted: position.state.threePlayerAttackProhibited, seat, stateHash: position.stateHash, wallMs: performance.now() - began, timing: job.timing, versions: result.versions, model: result.model, diagnostics: result.diagnostics });
        return { action: result.recommendedAction, stats: { work: result.diagnostics.work, completedDepth: result.diagnostics.completedDepth, cutoff: result.status === "limited" }, details: null };
      };
      const opponent = async (position: any) => ({ ...frozen.selector(position.state), details: null });
      const game = await playAnalysisSingles(start, seat, seatLineup(seat, "candidate", [frozen.id, frozen.id, frozen.id]), new Map([["candidate", candidate], [frozen.id, opponent]]), 16, async (step: any) => { events.push({ index: events.length, event: { type: "action", side: step.side, action: step.decision.action } }); });
      samples.push(game.sample);
    }
    rows.push({ profile, restricted: start.position.state.threePlayerAttackProhibited, seed: start.start.seed, seriesId: start.start.seriesId, summary: summarizeSingles(samples), samples });
  }
  const reports = ["trial-100ms", "trial-500ms"].map(profile => { const selected = selections.filter((row: any) => row.profile === profile) as any[]; return { profile, budget: aiCpuProfiles[profile as keyof typeof aiCpuProfiles], requests: selected.length, modelUses: selected.filter(row => row.model.usedModelId === modelId && row.model.inferenceCount > 0).length, fallbacks: selected.filter(row => row.model.fallbackReason).length, timing: summarizeTimes(selected.map(row => row.wallMs)) }; });
  await Bun.write(process.env.PROFILE_OUTPUT!, JSON.stringify({ sourceCommit: codeVersion, modelId, opponent: frozen.metadata, setup: { openingPlies: 12, maxAdditionalPlies: 16, seed: 19410, seats: sides, scope: "Bun on Mac plus actual Linux AI service. Excludes Worker minimum delay and game clock. Tuning starts only; unfinished games remain censored." }, rows, reports, selections, complete: true }, null, 2) + "\n");
} finally { frozen.dispose(); }
